1	/**
2	 * name.com API v4 client (reseller). Auth: HTTP Basic (username:token).
3	 * Production: https://api.name.com  ·  Dev/sandbox: https://api.dev.name.com
4	 */
5	
6	import { SANDBOX } from "./sandbox";
7	
8	export function registrarConfigured(): boolean {
9	  return !!(process.env.NAMECOM_USERNAME && process.env.NAMECOM_TOKEN);
10	}
11	
12	/**
13	 * Inbound transfers additionally work in SANDBOX (staging) with synthetic
14	 * results, so the whole transfer-in flow — quote, submit, poll, cancel — can be
15	 * exercised end to end without touching the registrar or a real domain.
16	 */
17	export function transfersAvailable(): boolean {
18	  return SANDBOX || registrarConfigured();
19	}
20	
21	function baseUrl(): string {
22	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
23	}
24	
25	function authHeader(): string {
26	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
27	  return "Basic " + Buffer.from(raw).toString("base64");
28	}
29	
30	async function nc(
31	  method: string,
32	  path: string,
33	  body?: unknown,
34	  opts?: { nullOn404?: boolean }
35	): Promise<any> {
36	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
37	  const res = await fetch(`${baseUrl()}${path}`, {
38	    method,
39	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
40	    body: body ? JSON.stringify(body) : undefined,
41	    signal: AbortSignal.timeout(30_000),
42	  });
43	  const text = await res.text();
44	  let json: any = {};
45	  try {
46	    json = text ? JSON.parse(text) : {};
47	  } catch {
48	    /* non-JSON error body */
49	  }
50	  if (!res.ok) {
51	    // Some callers treat "absent" as a normal answer (e.g. polling a transfer
52	    // that has already dropped off the registrar's list) — let them opt in to a
53	    // null instead of an exception rather than string-matching an error message.
54	    if (opts?.nullOn404 && res.status === 404) return null;
55	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
56	    throw new Error(`name.com: ${msg}`);
57	  }
58	  return json;
59	}
60	
61	const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));
62	
63	/** Platform markup added to the registrar cost, as a percentage (admin-tunable via env). */
64	export function domainMarkupPct(): number {
65	  return Number(process.env.DOMAIN_MARKUP_PCT ?? 25);
66	}
67	
68	/** Retail (customer) price for a given registrar cost, markup applied. */
69	export function retailCents(costCents: number | null): number | null {
70	  if (costCents === null) return null;
71	  return Math.round(costCents * (1 + domainMarkupPct() / 100));
72	}
73	
74	export type DomainCheck = {
75	  domain: string;
76	  available: boolean;
77	  premium: boolean;
78	  priceCents: number | null; // RETAIL — what the customer pays (per year)
79	  costCents: number | null; // registrar cost (per year)
80	  renewCents: number | null; // RETAIL renewal price
81	};
82	
83	export async function checkDomains(domains: string[]): Promise<DomainCheck[]> {
84	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: domains });
85	  return (json.results ?? []).map((r: any) => {
86	    const cost = dollarsToCents(r.purchasePrice);
87	    const renewCost = dollarsToCents(r.renewalPrice ?? r.purchasePrice);
88	    return {
89	      domain: r.domainName,
90	      available: r.purchasable === true,
91	      premium: r.premium === true,
92	      priceCents: retailCents(cost),
93	      costCents: cost,
94	      renewCents: retailCents(renewCost),
95	    };
96	  });
97	}
