99	export type RegistrantContact = {
100	  firstName: string;
101	  lastName: string;
102	  address1: string;
103	  city: string;
104	  stateProvince: string;
105	  postalCode: string;
106	  country: string; // ISO-2
107	  phone: string; // +NN.NNNNNNNNNN
108	  email: string;
109	};
110	
111	function ncContact(c: RegistrantContact) {
112	  return {
113	    firstName: c.firstName,
114	    lastName: c.lastName,
115	    address1: c.address1,
116	    city: c.city,
117	    state: c.stateProvince,
118	    zip: c.postalCode,
119	    country: c.country,
120	    phone: c.phone,
121	    email: c.email,
122	  };
123	}
