125	/** Registers for `years` at the given expected price (from checkDomains). */
126	export async function registerDomain(
127	  domain: string,
128	  years: number,
129	  contact: RegistrantContact,
130	  purchaseCents: number
131	): Promise<{ expiresAt?: Date }> {
132	  const c = ncContact(contact);
133	  const json = await nc("POST", "/v4/domains", {
134	    domain: {
135	      domainName: domain,
136	      contacts: { registrant: c, admin: c, tech: c, billing: c },
137	      privacyEnabled: true,
138	    },
139	    purchasePrice: purchaseCents / 100,
140	    years,
141	  });
142	  const exp = json?.domain?.expireDate ?? json?.order?.expireDate;
143	  return { expiresAt: exp ? new Date(exp) : undefined };
144	}
145	
146	export async function renewDomain(domain: string, years: number, purchaseCents: number): Promise<void> {
147	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:renew`, {
148	    purchasePrice: purchaseCents / 100,
149	    years,
150	  });
151	}
152	
153	export async function domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }> {
154	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}`);
155	  return {
156	    expires: json?.expireDate ? new Date(json.expireDate) : undefined,
157	    created: json?.createDate ? new Date(json.createDate) : undefined,
158	  };
159	}
