161	// ---------- Inbound transfers (transfer-in) ----------
162	//
163	// name.com v4 transfers:
164	//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
165	//   GET  /v4/transfers                      -> { transfers: [...] }
166	//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
167	//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
168	//
169	// A transfer always includes a 1-year extension of the registration, which is
170	// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
171	// registration rate.
172	
173	/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
174	const SANDBOX_APPROVAL_MS = 2 * 60_000;
175	const SANDBOX_REGISTRY_MS = 5 * 60_000;
176	
177	/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
178	function sandboxTldCostCents(domain: string): number {
179	  const tld = domain.slice(domain.lastIndexOf(".") + 1);
180	  let h = 0;
181	  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
182	  return 900 + (h % 21) * 50; // $9.00 – $19.00
183	}
184	
185	export type TransferCheck = {
186	  domain: string;
187	  /** True when we believe an inbound transfer can be submitted for this name. */
188	  transferable: boolean;
189	  /** Plain-English reason when `transferable` is false. */
190	  reason: string | null;
191	  premium: boolean;
192	  /** RETAIL price the customer pays — covers the transfer + 1 extra year. */
193	  priceCents: number | null;
194	  /** Registrar cost we pay name.com (what we send as `purchasePrice`). */
195	  costCents: number | null;
196	};
197	
198	/**
199	 * The registrar cost of transferring `domain`, in integer cents.
200	 *
201	 * Transfers are billed at the TLD's renewal rate. name.com only reliably prices
202	 * a name it can see, so we try three sources in order and give up honestly:
203	 *   1. the availability result for the domain itself,
204	 *   2. the per-domain pricing endpoint,
205	 *   3. a throwaway probe name on the same TLD — TLD pricing is per-TLD, so an
206	 *      unregistered sibling quotes the same renewal rate.
207	 */
208	async function transferCostCents(domain: string, availability: any): Promise<number | null> {
209	  const own = dollarsToCents(availability?.renewalPrice ?? availability?.purchasePrice);
210	  if (own !== null && own > 0) return own;
211	
212	  try {
213	    const p = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getPricing`);
214	    const quoted = dollarsToCents(p?.transferPrice ?? p?.renewalPrice ?? p?.purchasePrice);
215	    if (quoted !== null && quoted > 0) return quoted;
216	  } catch {
217	    /* endpoint unavailable for this TLD/account — fall through to the probe */
218	  }
219	
220	  const tld = domain.slice(domain.indexOf(".") + 1);
221	  try {
222	    const probe = `nxeon-price-probe-${Math.random().toString(36).slice(2, 10)}.${tld}`;
223	    const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [probe] });
224	    const r = (json.results ?? [])[0];
225	    const c = dollarsToCents(r?.renewalPrice ?? r?.purchasePrice);
226	    if (c !== null && c > 0) return c;
227	  } catch {
228	    /* registrar unhappy — no price, caller surfaces that plainly */
229	  }
230	  return null;
231	}
232	
233	/**
234	 * Can this domain be transferred in, and what would it cost? Never throws for a
235	 * "no" answer — a non-transferable name comes back with `transferable: false`
236	 * and a reason the customer can act on.
237	 */
238	export async function checkTransfer(domain: string): Promise<TransferCheck> {
239	  if (SANDBOX) {
240	    // Synthetic: everything is transferable except names containing "locked",
241	    // which exercise the rejected-quote path in staging.
242	    const cost = sandboxTldCostCents(domain);
243	    if (domain.includes("locked")) {
244	      return {
245	        domain,
246	        transferable: false,
247	        reason: "This domain is locked at its current registrar. Unlock it there and try again.",
248	        premium: false,
249	        priceCents: null,
250	        costCents: null,
251	      };
252	    }
253	    return {
254	      domain,
255	      transferable: true,
256	      reason: null,
257	      premium: false,
258	      priceCents: retailCents(cost),
259	      costCents: cost,
260	    };
261	  }
262	
263	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [domain] });
264	  const r = (json.results ?? [])[0];
265	  if (!r) {
266	    return {
267	      domain,
268	      transferable: false,
269	      reason: "We couldn't look this domain up at the registrar. Check the spelling and try again.",
270	      premium: false,
271	      priceCents: null,
272	      costCents: null,
273	    };
274	  }
275	  // Purchasable means nobody owns it — there is nothing to transfer.
276	  if (r.purchasable === true) {
277	    return {
278	      domain,
279	      transferable: false,
280	      reason: "This domain isn't registered anywhere yet, so there's nothing to transfer — register it instead.",
281	      premium: r.premium === true,
282	      priceCents: null,
283	      costCents: null,
284	    };
285	  }
286	  if (r.premium === true) {
287	    return {
288	      domain,
289	      transferable: false,
290	      reason: "Premium domains can't be transferred in automatically — contact support.",
291	      premium: true,
292	      priceCents: null,
293	      costCents: null,
294	    };
295	  }
296	
297	  const cost = await transferCostCents(domain, r);
298	  if (cost === null) {
299	    return {
300	      domain,
301	      transferable: false,
302	      reason: "We can't get a transfer price for this TLD from the registrar right now — contact support.",
303	      premium: false,
304	      priceCents: null,
305	      costCents: null,
306	    };
307	  }
308	  return { domain, transferable: true, reason: null, premium: false, priceCents: retailCents(cost), costCents: cost };
309	}
310	
311	export type TransferInfo = {
312	  domain: string;
313	  /** Raw registrar status, shown to the customer verbatim. */
314	  status: string;
315	  /** Where the losing registrar sent the approval email (not every TLD sends one). */
316	  email: string | null;
317	};
318	
319	/**
320	 * Submit an inbound transfer. `purchaseCents` is the registrar COST (integer
321	 * cents) — the same "what we expect to pay" contract `registerDomain` uses.
322	 * The auth code is passed straight through and never logged.
323	 */
324	export async function createTransfer(
325	  domain: string,
326	  authCode: string,
327	  purchaseCents: number
328	): Promise<TransferInfo> {
329	  if (SANDBOX) {
330	    // Names containing "fail" reject at submit time so staging can exercise the
331	    // "registrar refused, customer not charged" path.
332	    if (domain.includes("fail")) throw new Error("name.com: transfer rejected by the registry (sandbox)");
333	    return { domain, status: "pendingOwnerApproval", email: `owner@${domain}` };
334	  }
335	  const json = await nc("POST", "/v4/transfers", {
336	    domainName: domain,
337	    authCode,
338	    privacyEnabled: true,
339	    purchasePrice: purchaseCents / 100,
340	  });
341	  const t = json?.transfer ?? json ?? {};
342	  return {
343	    domain: t.domainName ?? domain,
344	    status: String(t.status ?? "pending"),
345	    email: t.email ? String(t.email) : null,
346	  };
347	}
348	
349	/**
350	 * Current state of an inbound transfer. Returns null when the registrar has no
351	 * transfer for this domain — which is a NORMAL answer once a transfer settles
352	 * and drops off the list, so callers must resolve that against `domainInfo`
353	 * rather than treating it as a failure.
354	 *
355	 * `startedAt` is only read in SANDBOX, where it drives a synthetic progression
356	 * (registrar.ts holds no state of its own).
357	 */
358	export async function getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null> {
359	  if (SANDBOX) {
360	    const age = Date.now() - (startedAt?.getTime() ?? Date.now());
361	    const status =
362	      age < SANDBOX_APPROVAL_MS
363	        ? "pendingOwnerApproval"
364	        : age < SANDBOX_REGISTRY_MS
365	          ? "pendingRegistry"
366	          : "completed";
367	    return { domain, status, email: `owner@${domain}` };
368	  }
369	  const t = await nc("GET", `/v4/transfers/${encodeURIComponent(domain)}`, undefined, { nullOn404: true });
370	  if (!t) return null;
371	  return {
372	    domain: t.domainName ?? domain,
373	    status: String(t.status ?? "pending"),
374	    email: t.email ? String(t.email) : null,
375	  };
376	}
377	
378	/**
379	 * Ask the registrar to cancel an in-flight inbound transfer. Throws if the
380	 * registrar refuses (e.g. the transfer already completed at the registry) —
381	 * callers must NOT credit the customer unless this resolves.
382	 */
383	export async function cancelTransfer(domain: string): Promise<TransferInfo> {
384	  if (SANDBOX) return { domain, status: "cancelled", email: null };
385	  const t = await nc("POST", `/v4/transfers/${encodeURIComponent(domain)}:cancel`, {});
386	  return {
387	    domain: t?.domainName ?? domain,
388	    status: String(t?.status ?? "cancelled"),
389	    email: t?.email ? String(t.email) : null,
390	  };
391	}
392	
393	/** All inbound transfers on the reseller account (ops/debug — not used per-domain). */
394	export async function listTransfers(): Promise<TransferInfo[]> {
395	  if (SANDBOX) return [];
396	  const json = await nc("GET", "/v4/transfers");
397	  return (json.transfers ?? []).map((t: any) => ({
398	    domain: t.domainName,
399	    status: String(t.status ?? "pending"),
400	    email: t.email ? String(t.email) : null,
401	  }));
402	}
403	
404	/** Bucket a raw registrar transfer status into something we can act on. */
405	export function transferOutcome(status: string): "completed" | "failed" | "pending" {
406	  const s = status.toLowerCase();
407	  if (/(complete|success|transferred)/.test(s)) return "completed";
408	  if (/(cancel|reject|denied|fail|expired|refund|void)/.test(s)) return "failed";
409	  return "pending";
410	}
411	
412	/** Human label for a raw registrar transfer status. */
413	export function transferStatusLabel(status: string): string {
414	  const s = status.toLowerCase();
415	  if (/owner|admin|approval|contact/.test(s)) return "Waiting for you to approve the confirmation email";
416	  if (/registry|processing|progress/.test(s)) return "Submitted to the registry";
417	  if (/complete|success|transferred/.test(s)) return "Completed";
418	  if (/cancel/.test(s)) return "Cancelled";
419	  if (/reject|denied/.test(s)) return "Rejected by the losing registrar";
420	  if (/expired/.test(s)) return "Expired — the confirmation was never approved";
421	  return status;
422	}
