426	export type DnsRecord = {
427	  id: number;
428	  host: string; // "" = apex
429	  type: string;
430	  answer: string;
431	  ttl: number;
432	  priority?: number;
433	};
434	
435	export async function listRecords(domain: string): Promise<DnsRecord[]> {
436	  const json = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}/records`);
437	  return (json.records ?? []).map((r: any) => ({
438	    id: r.id,
439	    host: r.host ?? "",
440	    type: r.type,
441	    answer: r.answer,
442	    ttl: r.ttl ?? 300,
443	    priority: r.priority,
444	  }));
445	}
446	
447	export async function addRecord(
448	  domain: string,
449	  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
450	): Promise<void> {
451	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/records`, {
452	    host: rec.host,
453	    type: rec.type,
454	    answer: rec.answer,
455	    ttl: rec.ttl ?? 300,
456	    ...(rec.priority !== undefined ? { priority: rec.priority } : {}),
457	  });
458	}
459	
460	export async function deleteRecord(domain: string, id: number): Promise<void> {
461	  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/records/${id}`);
462	}
463	
464	/** Read-only view used by the DNS UI: apex host shown as "@". */
465	export type DnsHost = { name: string; type: string; address: string; ttl: number; mxPref?: number };
466	
467	export async function getDnsHosts(domain: string): Promise<DnsHost[]> {
468	  const recs = await listRecords(domain);
469	  return recs.map((r) => ({
470	    name: r.host === "" ? "@" : r.host,
471	    type: r.type,
472	    address: r.answer,
473	    ttl: r.ttl,
474	    mxPref: r.priority,
475	  }));
476	}
