1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "./db";
6	import { requireUser } from "./auth";
7	import {
8	  registrarConfigured,
9	  listRecords,
10	  addRecord,
11	  deleteRecord,
12	  type DnsRecord,
13	} from "./registrar";
14	
15	/* ------------------------------------------------------------------ *
16	 * DNS super-manager actions for the customer domain manager.
17	 *
18	 * Reuses lib/registrar.ts's DNS helpers (listRecords/addRecord/
19	 * deleteRecord) for all record mutations. name.com endpoints not exposed
20	 * by that helper (URL forwarding, registrar lock) are called directly via
21	 * a minimal Basic-auth client that mirrors lib/registrar.ts, exactly like
22	 * lib/actions-domains-advanced.ts does. Everything is ownership-checked and
23	 * degrades gracefully (persist intent + a clear note) when the registrar
24	 * isn't configured or a TLD/endpoint isn't supported.
25	 * ------------------------------------------------------------------ */
26	
27	function baseUrl(): string {
28	  return process.env.NAMECOM_ENV === "dev" ? "https://api.dev.name.com" : "https://api.name.com";
29	}
30	
31	function authHeader(): string {
32	  const raw = `${process.env.NAMECOM_USERNAME}:${process.env.NAMECOM_TOKEN}`;
33	  return "Basic " + Buffer.from(raw).toString("base64");
34	}
35	
36	async function nc(method: string, path: string, body?: unknown): Promise<any> {
37	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
38	  const res = await fetch(`${baseUrl()}${path}`, {
39	    method,
40	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
41	    body: body !== undefined ? JSON.stringify(body) : undefined,
42	    signal: AbortSignal.timeout(30_000),
43	  });
44	  const text = await res.text();
45	  let json: any = {};
46	  try {
47	    json = text ? JSON.parse(text) : {};
48	  } catch {
49	    /* non-JSON error body */
50	  }
51	  if (!res.ok) {
52	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
53	    throw new Error(`name.com: ${msg}`);
54	  }
55	  return json;
56	}
57	
58	function errMsg(e: unknown): string {
59	  return String(e instanceof Error ? e.message : e).slice(0, 200);
60	}
61	
62	async function ownedDomain(domainId: string) {
63	  const user = await requireUser();
64	  const domain = await db.domain.findUnique({ where: { id: domainId } });
65	  if (!domain) throw new Error("Not found");
66	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
67	  return { user, domain };
68	}
69	
70	async function ownedActiveDomain(domainId: string) {
71	  const ctx = await ownedDomain(domainId);
72	  if (ctx.domain.status !== "ACTIVE") throw new Error("Domain is not active");
73	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
74	  return ctx;
75	}
76	
77	/* A record shape the client can build for presets / imports. Host "" = apex. */
78	export type RecordInput = {
79	  host: string;
80	  type: string;
81	  answer: string;
82	  ttl?: number;
83	  priority?: number;
84	};
85	
86	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
87	
88	function normHost(h: string): string {
89	  const t = (h ?? "").trim();
90	  return ["@", ""].includes(t) ? "" : t.replace(/\.$/, "");
91	}
92	
93	/** True if `want` is already present in `existing` (host+type+answer, MX also priority). */
94	function recordExists(existing: DnsRecord[], want: RecordInput): boolean {
95	  const wh = normHost(want.host);
96	  const wa = want.answer.trim().toLowerCase();
97	  return existing.some((r) => {
98	    if (r.host !== wh) return false;
99	    if (r.type !== want.type) return false;
100	    if (r.answer.trim().toLowerCase() !== wa) return false;
101	    if (want.type === "MX" && want.priority !== undefined) return (r.priority ?? 10) === want.priority;
102	    return true;
103	  });
104	}
105	
106	const recordInputSchema = z.object({
107	  host: z.string().max(120).default(""),
108	  type: z.enum(RECORD_TYPES),
109	  answer: z.string().min(1).max(2000),
110	  ttl: z.coerce.number().int().min(60).max(86400).default(300),
111	  priority: z.coerce.number().int().min(0).max(65535).optional(),
112	});
113	
114	export type BulkResult = {
115	  error?: string;
116	  added?: string[];
117	  skipped?: string[];
118	  failed?: { record: string; reason: string }[];
119	  note?: string;
120	};
121	
122	function label(r: RecordInput): string {
123	  const h = normHost(r.host) || "@";
124	  const pri = r.type === "MX" && r.priority !== undefined ? `${r.priority} ` : "";
125	  return `${r.type} ${h} → ${pri}${r.answer}`;
126	}
127	
128	/**
129	 * Add many DNS records at once, skipping any that already exist. Powers the
130	 * quick-setup presets and DNS import. Ownership-checked; domain must be ACTIVE.
131	 */
132	export async function addDnsRecordsBulk(
133	  domainId: string,
134	  records: RecordInput[]
135	): Promise<BulkResult> {
136	  let ctx;
137	  try {
138	    ctx = await ownedActiveDomain(domainId);
139	  } catch (e) {
140	    return { error: errMsg(e) };
141	  }
142	  if (!Array.isArray(records) || records.length === 0) return { error: "No records to add." };
143	  if (records.length > 100) return { error: "Too many records in one request (max 100)." };
144	
145	  const clean: RecordInput[] = [];
146	  for (const raw of records) {
147	    const parsed = recordInputSchema.safeParse(raw);
148	    if (!parsed.success) {
149	      return { error: `Invalid record: ${parsed.error.issues[0]?.message ?? "bad record"}` };
150	    }
151	    clean.push({ ...parsed.data, host: normHost(parsed.data.host) });
152	  }
153	
154	  let existing: DnsRecord[];
155	  try {
156	    existing = await listRecords(ctx.domain.name);
157	  } catch (e) {
158	    return { error: `Could not read current records: ${errMsg(e)}` };
159	  }
160	
161	  const added: string[] = [];
162	  const skipped: string[] = [];
163	  const failed: { record: string; reason: string }[] = [];
164	
165	  for (const rec of clean) {
166	    if (recordExists(existing, rec)) {
167	      skipped.push(label(rec));
168	      continue;
169	    }
170	    try {
171	      await addRecord(ctx.domain.name, {
172	        host: rec.host,
173	        type: rec.type,
174	        answer: rec.answer,
175	        ttl: rec.ttl ?? 300,
176	        priority: rec.type === "MX" || rec.type === "SRV" ? rec.priority ?? 10 : undefined,
177	      });
178	      added.push(label(rec));
179	      // Track locally so later records in the same batch dedupe correctly.
180	      existing.push({ id: -1, host: rec.host, type: rec.type, answer: rec.answer, ttl: rec.ttl ?? 300, priority: rec.priority });
181	    } catch (e) {
182	      failed.push({ record: label(rec), reason: errMsg(e) });
183	    }
184	  }
185	
186	  await db.auditLog.create({
187	    data: {
188	      userId: ctx.user.id,
189	      action: "domain.dns_bulk_add",
190	      detail: `${ctx.domain.name}: +${added.length} skip ${skipped.length} fail ${failed.length}`,
191	    },
192	  });
193	  revalidatePath(`/dashboard/domains/${domainId}`);
194	  return { added, skipped, failed: failed.length ? failed : undefined };
195	}
196	
197	/* ------------------------------------------------------------------ *
198	 * DNS import (paste) — CSV / zone-ish text: name,type,value[,ttl[,priority]]
199	 * Lines starting with # or ; are ignored. Whitespace or comma separated.
200	 * ------------------------------------------------------------------ */
201	
202	export type ParsedImport = { records: RecordInput[]; errors: string[] };
203	
204	/** Pure parser exported so the UI can preview before applying. */
205	export async function parseDnsImport(text: string): Promise<ParsedImport> {
206	  const records: RecordInput[] = [];
207	  const errors: string[] = [];
208	  const lines = (text ?? "").split(/\r?\n/);
209	  lines.forEach((line, i) => {
210	    const raw = line.trim();
211	    if (!raw || raw.startsWith("#") || raw.startsWith(";")) return;
212	    // split on comma OR whitespace, but keep the value token intact if quoted
213	    let parts: string[];
214	    if (raw.includes(",")) parts = raw.split(",").map((p) => p.trim());
215	    else parts = raw.split(/\s+/);
216	    if (parts.length < 3) {
217	      errors.push(`Line ${i + 1}: expected at least name, type, value`);
218	      return;
219	    }
220	    const [nameTok, typeTok, valueTok, ttlTok, prioTok] = parts;
221	    const type = typeTok.toUpperCase();
222	    if (!(RECORD_TYPES as readonly string[]).includes(type)) {
223	      errors.push(`Line ${i + 1}: unsupported type "${typeTok}"`);
224	      return;
225	    }
226	    const value = valueTok.replace(/^"|"$/g, "");
227	    const rec: RecordInput = { host: normHost(nameTok), type, answer: value };
228	    if (ttlTok && /^\d+$/.test(ttlTok)) rec.ttl = Math.min(86400, Math.max(60, Number(ttlTok)));
229	    if (type === "MX" && prioTok && /^\d+$/.test(prioTok)) rec.priority = Number(prioTok);
230	    records.push(rec);
231	  });
232	  return { records, errors };
233	}
234	
235	export async function importDnsRecords(domainId: string, text: string): Promise<BulkResult> {
236	  const { records, errors } = await parseDnsImport(text);
237	  if (errors.length && records.length === 0) {
238	    return { error: errors.join("; ").slice(0, 300) };
239	  }
240	  const res = await addDnsRecordsBulk(domainId, records);
241	  if (errors.length) {
242	    res.note = `${errors.length} line(s) skipped: ${errors.slice(0, 3).join("; ")}${errors.length > 3 ? "…" : ""}`;
243	  }
244	  return res;
245	}
246	
247	/* ------------------------------------------------------------------ *
248	 * Reset DNS to a sane default set (strong confirm handled in the UI).
249	 * Removes all customer-manageable records (A/AAAA/CNAME/TXT/MX/SRV/ALIAS),
250	 * leaves NS delegation untouched, then re-adds A @ / A www at the platform IP.
251	 * ------------------------------------------------------------------ */
252	
253	export async function resetDnsToDefaults(domainId: string): Promise<BulkResult> {
254	  let ctx;
255	  try {
256	    ctx = await ownedActiveDomain(domainId);
257	  } catch (e) {
258	    return { error: errMsg(e) };
259	  }
260	  const ip = process.env.PUBLIC_IP;
261	  const removable = new Set(["A", "AAAA", "CNAME", "TXT", "MX", "SRV", "ALIAS"]);
262	  let removed = 0;
263	  const failed: { record: string; reason: string }[] = [];
264	  try {
265	    const recs = await listRecords(ctx.domain.name);
266	    for (const r of recs) {
267	      if (!removable.has(r.type)) continue;
268	      try {
269	        await deleteRecord(ctx.domain.name, r.id);
270	        removed++;
271	      } catch (e) {
272	        failed.push({ record: `${r.type} ${r.host || "@"}`, reason: errMsg(e) });
273	      }
274	    }
275	  } catch (e) {
276	    return { error: `Could not read current records: ${errMsg(e)}` };
277	  }
278	
279	  const added: string[] = [];
280	  if (ip) {
281	    for (const host of ["", "www"]) {
282	      try {
283	        await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
284	        added.push(`A ${host || "@"} → ${ip}`);
285	      } catch (e) {
286	        failed.push({ record: `A ${host || "@"}`, reason: errMsg(e) });
287	      }
288	    }
289	  }
290	
291	  await db.auditLog.create({
292	    data: { userId: ctx.user.id, action: "domain.dns_reset", detail: `${ctx.domain.name}: removed ${removed}, added ${added.length}` },
293	  });
294	  revalidatePath(`/dashboard/domains/${domainId}`);
295	  return {
296	    added,
297	    skipped: [],
298	    failed: failed.length ? failed : undefined,
299	    note: `Removed ${removed} record(s)${added.length ? ` and restored a default A record set pointing at ${ip}` : " (no platform IP configured, so no default records were added)"}.`,
300	  };
301	}
302	
303	/* ------------------------------------------------------------------ *
304	 * URL forwarding / redirects (name.com URL-forwarding API).
305	 *   GET/POST/DELETE /v4/domains/{domain}/url/forwarding[/{host}]
306	 * Degrades to a persisted-intent Setting + note when unconfigured.
307	 * ------------------------------------------------------------------ */
308	
309	export type Redirect = { host: string; forwardsTo: string; type: string };
310	
311	const redirectStoreKey = (domainId: string) => `domain-redirect:${domainId}`;
312	
313	async function readRedirectIntent(domainId: string): Promise<Redirect[]> {
314	  const s = await db.setting.findUnique({ where: { key: redirectStoreKey(domainId) } });
315	  if (!s?.value) return [];
316	  try {
317	    const parsed = JSON.parse(s.value);
318	    return Array.isArray(parsed) ? parsed : [];
319	  } catch {
320	    return [];
321	  }
322	}
323	
324	async function writeRedirectIntent(domainId: string, list: Redirect[]): Promise<void> {
325	  await db.setting.upsert({
326	    where: { key: redirectStoreKey(domainId) },
327	    create: { key: redirectStoreKey(domainId), value: JSON.stringify(list) },
328	    update: { value: JSON.stringify(list) },
329	  });
330	}
331	
332	export type RedirectsView = { forwards: Redirect[]; live: boolean; note?: string; error?: string };
333	
334	/** List forwardings — live from name.com when possible, else persisted intent. */
335	export async function listRedirects(domainId: string): Promise<RedirectsView> {
336	  let ctx;
337	  try {
338	    ctx = await ownedDomain(domainId);
339	  } catch (e) {
340	    return { forwards: [], live: false, error: errMsg(e) };
341	  }
342	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
343	    try {
344	      const json = await nc("GET", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`);
345	      const forwards: Redirect[] = (json.urlForwarding ?? json.urlForwardings ?? []).map((f: any) => ({
346	        host: f.host ?? "",
