469	export async function setRegistrarLock(domainId: string, locked: boolean): Promise<LockView> {
470	  let ctx;
471	  try {
472	    ctx = await ownedDomain(domainId);
473	  } catch (e) {
474	    return { locked: false, live: false, error: errMsg(e) };
475	  }
476	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
477	  let live = false;
478	  let note: string | undefined;
479	  if (canLive) {
480	    try {
481	      await nc("POST", `/v4/domains/${encodeURIComponent(ctx.domain.name)}:${locked ? "lock" : "unlock"}`, {});
482	      live = true;
483	      note = locked
484	        ? "Registrar lock enabled — the domain is protected against unauthorized transfers."
485	        : "Registrar lock disabled — the domain can now be transferred to another registrar.";
486	    } catch (e) {
487	      return { locked: !locked, live: false, error: `Registrar rejected the change: ${errMsg(e)}. Some TLDs manage the lock manually.` };
488	    }
489	  } else {
490	    note = "Saved. This lock preference will be applied at name.com once the domain is active and the registrar is connected.";
491	  }
492	  await db.setting.upsert({
493	    where: { key: lockStoreKey(domainId) },
494	    create: { key: lockStoreKey(domainId), value: String(locked) },
495	    update: { value: String(locked) },
496	  });
497	  await db.auditLog.create({
498	    data: { userId: ctx.user.id, action: "domain.registrar_lock", detail: `${ctx.domain.name} -> ${locked ? "locked" : "unlocked"}${live ? " (live)" : ""}` },
499	  });
500	  revalidatePath(`/dashboard/domains/${domainId}`);
501	  return { locked, live, note };
502	}
