"use client";

import { useActionState } from "react";
import { saveSettings } from "@/lib/actions-settings";

type Result = { ok?: boolean; error?: string };

/**
 * Card-shaped settings form. Binds `saveSettings` to a fixed section server-side
 * and wires the shared save bar. Children are field components (below); pass
 * `wide` to a field to make it span both grid columns.
 */
export function SettingsForm({
  section,
  title,
  desc,
  children,
}: {
  section: string;
  title: string;
  desc?: string;
  children: React.ReactNode;
}) {
  const [state, action, pending] = useActionState<Result, FormData>(
    saveSettings.bind(null, section),
    {},
  );

  return (
    <form action={action} className="card space-y-6 p-6">
      <div>
        <h2 className="text-lg font-semibold">{title}</h2>
        {desc && <p className="mt-1 text-sm text-slate-400">{desc}</p>}
      </div>

      <div className="grid gap-5 sm:grid-cols-2">{children}</div>

      <div className="flex items-center gap-3 border-t border-white/[0.06] pt-5">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save changes"}
        </button>
        {!pending && state?.ok && <span className="text-sm text-emerald-400">Saved.</span>}
        {!pending && state?.error && <span className="text-sm text-red-400">{state.error}</span>}
      </div>
    </form>
  );
}

function Wrap({ wide, children }: { wide?: boolean; children: React.ReactNode }) {
  return <div className={wide ? "sm:col-span-2" : ""}>{children}</div>;
}

function Hint({ hint }: { hint?: string }) {
  return hint ? <p className="mt-1 text-xs text-slate-500">{hint}</p> : null;
}

export function TextField({
  label,
  name,
  defaultValue,
  placeholder,
  type = "text",
  hint,
  wide,
  min,
  step,
}: {
  label: string;
  name: string;
  defaultValue?: string;
  placeholder?: string;
  type?: string;
  hint?: string;
  wide?: boolean;
  min?: number;
  step?: number | string;
}) {
  return (
    <Wrap wide={wide}>
      <label className="label" htmlFor={`s-${name}`}>
        {label}
      </label>
      <input
        id={`s-${name}`}
        className="input"
        name={name}
        type={type}
        defaultValue={defaultValue}
        placeholder={placeholder}
        min={min}
        step={step}
      />
      <Hint hint={hint} />
    </Wrap>
  );
}

/** Secret input: never receives the stored value. `isSet` only tweaks the copy. */
export function SecretField({
  label,
  name,
  isSet,
  hint,
  wide,
}: {
  label: string;
  name: string;
  isSet?: boolean;
  hint?: string;
  wide?: boolean;
}) {
  return (
    <Wrap wide={wide}>
      <label className="label" htmlFor={`s-${name}`}>
        {label}
      </label>
      <input
        id={`s-${name}`}
        className="input"
        name={name}
        type="password"
        autoComplete="new-password"
        placeholder={isSet ? "•••••••• (unchanged)" : "Not set"}
      />
      <Hint hint={hint ?? "Leave blank to keep the current value."} />
    </Wrap>
  );
}

