5	/**
6	 * Client tab shell for the settings hub. The page renders every panel (server-
7	 * and client-side alike) as ordered children; this component only shows/hides
8	 * them, so all forms stay mounted (and keep their unsaved state) as you switch
9	 * tabs. Data is fetched once, server-side, in the page.
10	 *
11	 * Deep-links via `?tab=<id>`: `initial` seeds the active tab from the URL and
12	 * selecting a tab updates the query string without a navigation.
13	 */
14	export function SettingsTabs({
15	  tabs,
16	  initial,
17	  children,
18	}: {
19	  tabs: { id: string; label: string }[];
20	  initial?: string;
21	  children: React.ReactNode;
22	}) {
23	  const panels = Children.toArray(children);
24	  const first = tabs[0]?.id ?? "";
25	  const seed = initial && tabs.some((t) => t.id === initial) ? initial : first;
26	  const [active, setActive] = useState(seed);
27	
28	  function select(id: string) {
29	    setActive(id);
30	    if (typeof window !== "undefined") {
31	      const url = new URL(window.location.href);
32	      url.searchParams.set("tab", id);
33	      window.history.replaceState(null, "", url.toString());
34	    }
35	  }
36	
37	  return (
38	    <div className="space-y-6">
39	      <div
40	        role="tablist"
41	        aria-label="Settings sections"
42	        className="scrollbar-none flex gap-1 overflow-x-auto rounded-xl border border-white/[0.06] bg-white/[0.02] p-1"
43	      >
44	        {tabs.map((t) => {
45	          const on = t.id === active;
46	          return (
47	            <button
48	              key={t.id}
49	              type="button"
50	              role="tab"
51	              aria-selected={on}
52	              onClick={() => select(t.id)}
53	              className={`whitespace-nowrap rounded-lg px-3.5 py-2 text-sm font-medium transition-colors ${
54	                on
55	                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow"
56	                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
57	              }`}
58	            >
59	              {t.label}
60	            </button>
61	          );
62	        })}
63	      </div>
64	
65	      {tabs.map((t, i) => (
66	        <div key={t.id} role="tabpanel" hidden={t.id !== active}>
67	          {panels[i]}
68	        </div>
69	      ))}
70	    </div>
71	  );
72	}
